{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count described in the task: each round every
 * ballot counts for its most-preferred still-continuing candidate, and
 * exactly one candidate is eliminated per round until someone has a
 * majority of the ballots that counted for anyone, or none do.
 */

/**
 * Breaks a tie for fewest votes among `tied` candidates. `history` holds,
 * for every round counted so far (1-indexed, `history[0]` unused), a map
 * from candidate name to that round's vote count. Compares the tied
 * candidates round by round from the first round, narrowing to whichever
 * of them had the fewest votes at the first round where they disagree, and
 * restarting the comparison from the first round with the narrowed group.
 * When no round ever separates them, the candidate whose name sorts last
 * by code point is eliminated.
 */
function breakTie(tied, history, roundCount) {
  let group = tied.slice()
  while (group.length > 1) {
    let narrowed = null
    for (let round = 1; round <= roundCount; round++) {
      const counts = history[round]
      const values = group.map((name) => counts.get(name))
      const allEqual = values.every((value) => value === values[0])
      if (!allEqual) {
        const min = Math.min(...values)
        narrowed = group.filter((name) => counts.get(name) === min)
        break
      }
    }
    if (narrowed === null) {
      group.sort()
      return group[group.length - 1]
    }
    group = narrowed
  }
  return group[0]
}

/**
 * Counts the election. Returns `{ rounds, winner }`, where `rounds` is an
 * array of `{ counts, exhausted, eliminated }` (a `Map` of candidate name
 * to vote count, the number of ballots exhausted that round, and the name
 * eliminated that round or `null` when the round ended the election), and
 * `winner` is the winning candidate's name or `null` when nobody won.
 */
export function countElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = [null]
  const rounds = []
  let winner = null

  for (let roundNumber = 1; ; roundNumber++) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
      }
    }

    history.push(counts)
    const activeTotal = [...counts.values()].reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const majority = [...counts.entries()].find(([, votes]) => votes * 2 > activeTotal)
    if (majority) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = majority[0]
      break
    }

    const fewest = Math.min(...counts.values())
    const tied = [...counts.keys()].filter((name) => counts.get(name) === fewest)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history, roundNumber)

    rounds.push({ counts, exhausted, eliminated })
    continuing.delete(eliminated)
  }

