{"file_path":"src/format.js","content":"/**
 * Renders the counted election as the lines the CLI prints, one round per
 * line (plus an `eliminated` line where applicable) for `rounds` mode, or a
 * single round count for `tally` mode. Neither includes the trailing
 * `winner <name>` / `no winner` line; the caller appends that.
 */

function formatRound(roundNumber, counts, exhausted) {
  const entries = [...counts.entries()]
  entries.sort(([nameA, votesA], [nameB, votesB]) => votesB - votesA || (nameA < nameB ? -1 : nameA > nameB ? 1 : 0))
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

export function formatOutcomeLine(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

export function formatRoundsMode(result) {
  const lines = []
  result.rounds.forEach((round, index) => {
